import{_ as i,C as n,o as a,c as o,a4 as s,b as l,w as t,a as p,E as d,a5 as c}from"./chunks/framework.DIAVNHHO.js";const f=JSON.parse('{"title":"WEBGL入门","description":"","frontmatter":{},"headers":[],"relativePath":"web3d/three/index.md","filePath":"web3d/three/index.md","lastUpdated":1774404591000}'),b={name:"web3d/three/index.md"};function h(m,e,_,g,G,D){const r=n("Mermaid");return a(),o("div",null,[e[1]||(e[1]=s('<h1 id="webgl入门" tabindex="-1">WEBGL入门 <a class="header-anchor" href="#webgl入门" aria-label="Permalink to &quot;WEBGL入门&quot;">​</a></h1><h2 id="什么是webgl" tabindex="-1">什么是webGl <a class="header-anchor" href="#什么是webgl" aria-label="Permalink to &quot;什么是webGl&quot;">​</a></h2><p>WebGL（全写Web Graphics Library）是一种3D绘图协议，这种绘图技术标准允许把JavaScript和OpenGL ES 2.0结合在一起，通过增加OpenGL ES 2.0的一个JavaScript绑定，WebGL可以为`HTML5 Canvas提供硬件3D加速渲染，这样Web开发人员就可以借助系统显卡来在浏览器里更流畅地展示3D场景和模型了，还能创建 <strong>复杂的导航和数据视觉化</strong>。 显然，WebGL技术标准免去了开发网页专用渲染插件的麻烦，可被用于创建具有复杂3D结构的网站页面，甚至可以用来设计3D网页游戏等等</p><h2 id="渲染管线" tabindex="-1">渲染管线 <a class="header-anchor" href="#渲染管线" aria-label="Permalink to &quot;渲染管线&quot;">​</a></h2><p>渲染管线(rendering pipeline)，又称图形学管线(graphics pipeline)，是计算机将 3D 模型渲染至 2D 屏幕上的一个概念模型。</p><p>渲染管线，其实就是图形的渲染过程。</p><p>Webgl的渲染依赖底层GPU的渲染能力。所以WEBGL 渲染流程和 GPU 内部的渲染管线是相符的。 渲染管线的<strong>作用是将3D模型转换为2维图像</strong>。</p><p>渲染管线一般分为 4 个部分，应用(Application)、几何处理(Geometry Processing)、光栅化(Rasterization) 和 像素处理(Pixel Processing)。不同资料、不同实现可能有不同的划分方法，但总体的流程是相似的。</p>',8)),(a(),l(c,null,{default:t(()=>[d(r,{id:"mermaid-24",class:"mermaid",graph:"%0Aflowchart%20LR%0A%20%20%20%20A%5BApplication%5D%20--%3E%20B%5BGeometry%20Processing%5D%0A%20%20%20%20B%20--%3E%20C%5BRasterization%5D%0A%20%20%20%20C%20--%3E%20D%5BPixel%20Processing%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1}))])}const u=i(b,[["render",h]]);export{f as __pageData,u as default};
